-- 18. Conclusion of the First Part
insert into public.pooja_steps
  (pooja_id, step_number, phase, step_title_en, step_title_ta,
   instruction_en, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, modes, gender_rule, scripts_generated, source_ref)
values
  ('sandhyavandanam', 18, 'purvangam', 'Conclusion of the First Part', 'முதல் பகுதி நிறைவு',
   'Take water in the hand and pour it onto the plate as an offering while reciting.',
   'मया कृतं इदं सर्वं कर्म ओं तत् सत् ब्रह्मार्पणमस्तु',
   'மயா க்ருதம் இதம் ஸர்வம் கர்ம ஓம் தத் ஸத் ப்ரஹ்மார்பணமஸ்து',
   'mayā kṛtaṃ idaṃ sarvaṃ karma oṃ tat sat brahmārpaṇamastu',
   'Whatever I have done, all of it — om tat sat — let it be an offering to Brahman.',
   'The book seals its own half here and says so: the first part of the sandhyavandanam ends, and then iti praatah sandhyaavandanam. What follows is the japa, which has its own sankalpa and its own name. The seal hands the work back rather than claiming it, and the japa half will end with the same words.',
   array['pratah', 'madhyahnika', 'sayam']::text[], 'all', true, 'Yajurveda Trikaala Sandhyaavandanam (Giri), pp.16-27, photographed page');

-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam';
  if n <> 18 then raise exception 'expected 18 steps, found %', n; end if;

  -- Step numbers dense from 1, which the app relies on for the jump list.
  select count(*) into n from (
    select step_number, row_number() over (order by step_number) as rn
      from public.pooja_steps where pooja_id = 'sandhyavandanam'
  ) t where t.step_number <> t.rn;
  if n > 0 then raise exception '% step(s) are not numbered 1..n', n; end if;

  -- Every sitting is walkable end to end.
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and 'pratah' = any(modes);
  if n <> 14 then raise exception 'pratah has % steps, expected 14', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and 'madhyahnika' = any(modes);
  if n <> 14 then raise exception 'madhyahnika has % steps, expected 14', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and 'sayam' = any(modes);
  if n <> 14 then raise exception 'sayam has % steps, expected 14', n; end if;

  -- The misprints are gone and the corrections are present. Asserted on the
  -- stored rows, not on the generator's own variables.
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and mantra_sanskrit like '%यो वशिशवतमो रसः%';
  if n > 0 then raise exception '% step(s) still carry the misprint यो वशिशवतमो रसः', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and mantra_sanskrit like '%ओं भूर्भुवस्तुवः।%';
  if n > 0 then raise exception '% step(s) still carry the misprint ओं भूर्भुवस्तुवः।', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and mantra_sanskrit like '%त्रिविक्रमं तर्पयामिा%';
  if n > 0 then raise exception '% step(s) still carry the misprint त्रिविक्रमं तर्पयामिा', n; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'sandhyavandanam' and mantra_sanskrit like '%यो वः शिवतमो रसः%';
  if n <> 2 then raise exception 'expected 2 steps with the corrected apo hi shtha line, found %', n; end if;

  -- The tarpanam is twenty-one offerings, and none of them is a bare number
  -- the way the nitya tarpanam shipped in 0037.
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'sandhyavandanam' and s.step_title_en = 'Navagraha Deva Tarpanam';
  if n <> 21 then raise exception 'tarpanam has % offerings, expected 21', n; end if;
  select count(*) into n from public.archana_items a
    join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'sandhyavandanam' and a.invoked_name_deva !~ '[ऀ-ॿ]';
  if n > 0 then raise exception '% offering(s) carry no Devanagari', n; end if;

  -- No Devanagari leaked into the Tamil, which is the check that caught the
  -- gm nasal. Devanagari Extended included, which the original range missed.
  --
  -- THE DANDAS ARE STRIPPED FIRST. U+0964 and U+0965 sit inside the Devanagari
  -- block, but _tamil.mjs protects them deliberately: they are shared
  -- punctuation rather than letters, and every Tamil mantra in this app
  -- already carries them. The first draft of this assertion did not strip
  -- them and failed nine of eighteen steps over punctuation that belongs
  -- there. proofread has excluded them since the visarga gate was added.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'sandhyavandanam'
     and translate(coalesce(mantra_tamil, ''), '।॥', '') ~ '[ऀ-ॿ꣠-ꣿ]';
  if n > 0 then raise exception '% Tamil mantra(s) carry Devanagari', n; end if;

  -- Still planned. 0049 publishes it.
  select count(*) into n from public.poojas where id = 'sandhyavandanam' and status = 'planned';
  if n <> 1 then raise exception 'sandhyavandanam should still be planned until 0049'; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
